mapper.select:


    m.del_flag = '0'
    and m.baby_id = #{babyId}
    and m.tag_code = #{tagCode}
    and m.media_type = #{mediaType}

        and m.create_time >= to_timestamp(#{params.beginTime},'yyyy-MM-dd hh24:mi:ss')


        and m.create_time <= to_timestamp(#{params.endTime},'yyyy-MM-dd hh24:mi:ss')


order by m.create_time desc, m.media_id desc


where m.del_flag = '0' and m.baby_id = #{babyId}
order by m.create_time desc, m.media_id desc
limit #{limit}
